import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, consider the set of consecutive integers {lower, lower+1, ..., n}. A set has the [gon_sides]-gon property if it contains [gon_sides] distinct elements whose largest is strictly less than the sum of the other [gon_sides]-1 elements (so those [gon_sides] numbers can be the side lengths of a non-degenerate [gon_sides]-gon). Determine the largest integer n such that every [subset_size]-element subset of {lower, lower+1, ..., n} has the [gon_sides]-gon property.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters for the generalized polygon property.
# We aim for non-trivial instances where the answer is reasonably large
# and the recurrence doesn't blow up too large.
def compute_threshold(lower, r, s):
    # r-gon-free minimal sequence threshold: a_s via (r-1)-step sum recurrence
    a = []
    for i in range(s):
        if i < r - 1:
            a.append(lower + i)
        else:
            a.append(sum(a[i - (r - 1): i]))
    return a[-1]
for _ in range(100):
    r = rng.randint(3, 6)              # number of sides (triangle up to hexagon)
    s = rng.randint(r + 6, r + 11)     # ensure s is noticeably larger than r
    lower = rng.randint(3, 9)          # start of the consecutive set
    # Compute threshold a_s and answer n = a_s - 1
    a_s = compute_threshold(lower, r, s)
    n_ans = a_s - 1
    # Difficulty and size checks to avoid trivial or astronomically huge cases
    if n_ans < 100:
        continue
    if a_s > 5_000_000:
        continue
    return {'lower': lower, 'subset_size': s, 'gon_sides': r}
# Fallback to seed-like but generalized reasonable instance if retries exhausted
return {'lower': 4, 'subset_size': 10, 'gon_sides': 3}

    def verifier(assign):
# Validate presence and types
if not all(k in assign for k in ['lower', 'subset_size', 'gon_sides']):
    # Missing keys
    return (False, None)  # Missing required fields
lower = assign['lower']
s = assign['subset_size']
r = assign['gon_sides']
# Basic domain checks
if not (isinstance(lower, int) and isinstance(s, int) and isinstance(r, int)):
    return (False, None)  # Types must be integers
if lower < 2:
    return (False, None)  # Starting value must be at least 2
if r < 3:
    return (False, None)  # Polygon must have at least 3 sides
if s < r:
    return (False, None)  # Subset size must be at least r to even form an r-gon
# Compute the minimal r-gon-free sequence threshold a_s
a = []
for i in range(s):
    if i < r - 1:
        a.append(lower + i)
    else:
        # Sum of previous r-1 terms
        window_sum = 0
        for j in range(i - (r - 1), i):
            window_sum += a[j]
        a.append(window_sum)
a_s = a[-1]
# The largest n for which every s-element subset has the r-gon property is a_s - 1
answer = a_s - 1
# Additional difficulty enforcement: avoid trivial instances
if answer < 50:
    return (False, None)  # Instance too trivial; generator should avoid this
# Sanity check: for n = answer + 1, the constructed sequence lies within {lower,...,n}
# and is r-gon-free by construction (max equals sum of previous r-1), demonstrating tightness.
# This is a constructive validation of the upper bound direction.
# For n = answer, such an r-gon-free s-subset cannot exist by the extremal minimality lemma.
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

